-- Fakt kartochkalarining ruscha matni — 8-partiya:
-- Oybek, Zulfiya, Abdulla Qahhor, Said Ahmad, O'tkir Hoshimov.

-- ===== Oybek =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Каково настоящее имя Айбека и где он родился?', fact_ru = 'Я родился 10 января 1905 года в ташкентской махалле Говкуш. Моё настоящее имя — Муса Ташмухамедов, «Айбек» — мой псевдоним.' WHERE id = 271;
UPDATE fact_cards SET topic_ru = 'Начало моего творчества', question_ru = 'С какого года Айбек начал писать стихи?', fact_ru = 'Я начал писать стихи с 1922 года и творил до конца жизни.' WHERE id = 272;
UPDATE fact_cards SET topic_ru = 'Мои поэтические сборники', question_ru = 'Как называются первые поэтические сборники Айбека?', fact_ru = 'Мои сборники поры «Чувств» выходили в 1920–1930-х годах; среди них «Поход в науку» (1930) и «Выбор» (1935).' WHERE id = 273;
UPDATE fact_cards SET topic_ru = '«Священная кровь»', question_ru = 'Когда Айбек написал роман «Священная кровь»?', fact_ru = 'В 1940 году я написал свой роман «Священная кровь».' WHERE id = 274;
UPDATE fact_cards SET topic_ru = 'Роман «Навои»', question_ru = 'Когда вышел роман Айбека «Навои»?', fact_ru = 'Мой роман «Навои» вышел в 1944 году — он считается одним из крупнейших исторических романов узбекской литературы.' WHERE id = 275;
UPDATE fact_cards SET topic_ru = 'Мои другие романы', question_ru = 'Какие ещё романы написал Айбек?', fact_ru = 'Я написал романы «Ветры золотой долины» (1949), «Солнце не померкнет» (1954) и «Великий путь» (1963).' WHERE id = 276;
UPDATE fact_cards SET topic_ru = '«Детство»', question_ru = 'О чём повесть Айбека «Детство»?', fact_ru = 'В 1963 году я написал повесть-воспоминание «Детство» — в ней рассказано о моём собственном детстве.' WHERE id = 277;
UPDATE fact_cards SET topic_ru = 'Академик', question_ru = 'Когда Айбек стал действительным членом Академии наук?', fact_ru = 'В 1943 году я стал действительным членом Академии наук Узбекистана.' WHERE id = 278;
UPDATE fact_cards SET topic_ru = 'Мои переводы', question_ru = 'Произведения каких мировых писателей переводил Айбек?', fact_ru = 'Я перевёл на узбекский «Евгения Онегина» Пушкина, «Маскарад» Лермонтова и «Тартюфа» Мольера.' WHERE id = 279;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Айбек?', fact_ru = 'Я скончался 1 июля 1968 года в Ташкенте.' WHERE id = 280;
UPDATE fact_cards SET topic_ru = 'Где я учился', question_ru = 'В каком городе, кроме Ташкента, учился Айбек?', fact_ru = 'Я учился в Ташкенте и в Ленинграде по экономическому направлению. Затем преподавал студентам в университете.' WHERE id = 1758;
UPDATE fact_cards SET topic_ru = 'Моя супруга', question_ru = 'Как называется книга воспоминаний, написанная об Айбеке его супругой Зарифой Саиднасыровой?', fact_ru = 'Моя супруга Зарифа Саиднасырова была учёным-химиком. Она написала обо мне книгу воспоминаний «Мой Айбек».' WHERE id = 1759;
UPDATE fact_cards SET topic_ru = 'Моя Государственная премия', question_ru = 'За какое произведение Айбек получил Государственную премию в 1946 году?', fact_ru = 'За роман «Навои» я удостоился Государственной премии в 1946 году.' WHERE id = 1760;
UPDATE fact_cards SET topic_ru = 'Моя поэма о Навои', question_ru = 'Какое ещё произведение об Алишере Навои написал Айбек, кроме романа?', fact_ru = 'До романа «Навои» я написал о великом поэте и поэму под названием «Навои». Образ Алишера Навои был одной из главных тем моего творчества.' WHERE id = 1761;
UPDATE fact_cards SET topic_ru = 'Моя работа в Союзе писателей', question_ru = 'Какую творческую организацию возглавлял Айбек?', fact_ru = 'В послевоенные годы я возглавлял Союз писателей Узбекистана.' WHERE id = 1762;
UPDATE fact_cards SET topic_ru = 'Мой дом-музей', question_ru = 'В каком городе находится дом-музей Айбека?', fact_ru = 'В Ташкенте, в доме, где я жил, сейчас работает дом-музей Айбека. Там хранятся мои рукописи и личные вещи.' WHERE id = 1763;
UPDATE fact_cards SET topic_ru = 'Места моего имени', question_ru = 'Какая станция Ташкентского метро названа именем Айбека?', fact_ru = 'Одна из станций Ташкентского метро и несколько улиц названы моим именем.' WHERE id = 1764;

-- ===== Zulfiya =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родилась Зульфия?', fact_ru = 'Я родилась 1 марта 1915 года в Ташкенте, в семье ремесленника. Моё полное имя — Зульфия Исраилова.' WHERE id = 311;
UPDATE fact_cards SET topic_ru = 'Моя учёба', question_ru = 'Где Зульфия начала пробовать себя в стихах?', fact_ru = 'В 1931–1934 годах я училась в женском училище, а первые опыты в стихах начала в литературном кружке.' WHERE id = 312;
UPDATE fact_cards SET topic_ru = 'Мой научный путь', question_ru = 'В каком институте училась Зульфия?', fact_ru = 'В 1935–1938 годах я училась в Институте языка и литературы Академии наук.' WHERE id = 313;
UPDATE fact_cards SET topic_ru = 'Моя первая книга', question_ru = 'Как называется первый поэтический сборник Зульфии?', fact_ru = 'В 1932 году вышел мой первый поэтический сборник «Страницы жизни».' WHERE id = 314;
UPDATE fact_cards SET topic_ru = 'Мои книги', question_ru = 'Какие сборники Зульфии были изданы?', fact_ru = 'Изданы мои сборники «Песня девушек» (1938), «В дни разлуки» (1944), «Песня зари» (1953) и «Мои напевы вам» (1965).' WHERE id = 315;
UPDATE fact_cards SET topic_ru = 'Оперные либретто', question_ru = 'По поэмам какого поэта Зульфия создала оперные либретто?', fact_ru = 'Я создала оперные либретто по поэмам Хамида Алимджана.' WHERE id = 316;
UPDATE fact_cards SET topic_ru = 'Делийская конференция', question_ru = 'Под впечатлением какой поездки родилось произведение Зульфии «Мушоира»?', fact_ru = 'В 1956 году я участвовала в конференции писателей Азии и Африки в Дели; под впечатлением этой поездки родилось моё произведение «Мушоира» (1958).' WHERE id = 317;
UPDATE fact_cards SET topic_ru = 'Мои международные награды', question_ru = 'Какие международные награды получила Зульфия?', fact_ru = 'За стихи об Индии я получила международную премию имени Джавахарлала Неру, а за мир — премию «Лотос».' WHERE id = 318;
UPDATE fact_cards SET topic_ru = 'Переводы', question_ru = 'На какие языки переведены стихи Зульфии?', fact_ru = 'Мои стихи переведены на русский, английский, немецкий, хинди, болгарский, китайский, арабский и персидский языки.' WHERE id = 319;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'В каком возрасте умерла Зульфия?', fact_ru = 'Я скончалась 1 августа 1996 года в возрасте 81 года.' WHERE id = 320;
UPDATE fact_cards SET topic_ru = 'Мой супруг', question_ru = 'Какой поэт был супругом Зульфии?', fact_ru = 'Моим супругом был известный поэт Хамид Алимджан. Мы создали семью в 1935 году, и он был мне самым близким единомышленником.' WHERE id = 1835;
UPDATE fact_cards SET topic_ru = '«Весна пришла, тебя спросив»', question_ru = 'Чьей памяти посвящено стихотворение Зульфии «Весна пришла, тебя спросив»?', fact_ru = 'Хамид Алимджан безвременно скончался в 1944 году. Его памяти я посвятила много стихов, среди них и «Весна пришла, тебя спросив».' WHERE id = 1836;
UPDATE fact_cards SET topic_ru = 'Журнал «Саодат»', question_ru = 'Каким журналом Зульфия много лет руководила как главный редактор?', fact_ru = 'Много лет я работала главным редактором женского журнала «Саодат».' WHERE id = 1837;
UPDATE fact_cards SET topic_ru = 'Моё звание', question_ru = 'Какого почётного звания удостоилась Зульфия?', fact_ru = 'В 1965 году мне было присвоено почётное звание «Народная поэтесса Узбекистана».' WHERE id = 1838;
UPDATE fact_cards SET topic_ru = 'Мои поездки', question_ru = 'В страны каких континентов ездила Зульфия с литературными поездками?', fact_ru = 'В составе писательских делегаций я побывала во многих странах Азии и Африки и знакомила мир с узбекской литературой.' WHERE id = 1839;
UPDATE fact_cards SET topic_ru = 'Премия моего имени', question_ru = 'Кому вручается Государственная премия имени Зульфии?', fact_ru = 'Я умерла в 1996 году. После моей смерти, в 1999 году, в Узбекистане была учреждена Государственная премия имени Зульфии. Её вручают одарённым девушкам.' WHERE id = 1840;
UPDATE fact_cards SET topic_ru = 'Моё столетие', question_ru = 'Когда отмечалось 100-летие со дня рождения Зульфии?', fact_ru = 'Я умерла в 1996 году. Но мои стихи остались жить: в 2015 году в Узбекистане широко отмечалось 100-летие со дня моего рождения, прошли мероприятия, посвящённые моему творчеству.' WHERE id = 1841;

-- ===== Abdulla Qahhor =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Абдулла Каххар?', fact_ru = 'Я родился 17 сентября 1907 года в городе Коканд.' WHERE id = 1936;
UPDATE fact_cards SET topic_ru = 'Моё образование', question_ru = 'Где получил образование Абдулла Каххар?', fact_ru = 'В 1930 году я окончил педагогический факультет Среднеазиатского государственного университета.' WHERE id = 1937;
UPDATE fact_cards SET topic_ru = 'Начало творчества', question_ru = 'В каком журнале и под каким псевдонимом напечатано первое стихотворение Абдуллы Каххара?', fact_ru = 'Моё первое сатирическое стихотворение «Когда сгорела луна» напечатано в 1924 году в журнале «Муштум» под псевдонимом «Норин шилпик».' WHERE id = 1938;
UPDATE fact_cards SET topic_ru = 'Я как рассказчик', question_ru = 'Как называется первый сборник рассказов Абдуллы Каххара и когда он издан?', fact_ru = 'Известность как рассказчик началась у меня с рассказа «Человек без головы», написанного в 1929 году. Мой первый сборник рассказов «Мир молодеет» издан в 1935 году.' WHERE id = 1939;
UPDATE fact_cards SET topic_ru = 'Мой роман «Мираж»', question_ru = 'Когда написан роман Абдуллы Каххара «Мираж»?', fact_ru = 'Свой первый роман «Мираж» я написал в 1935 году. Позже, в 1951 году, вышел мой роман «Огни Кошчинара».' WHERE id = 1940;
UPDATE fact_cards SET topic_ru = 'Мои повести', question_ru = 'Когда написана повесть Абдуллы Каххара «Сказки о былом»?', fact_ru = 'Повесть «Синичка» я написал в 1958 году, «Сказки о былом» — в 1965 году, а «Любовь» — в 1968 году. Эти повести стали вкладом в развитие узбекской прозы.' WHERE id = 1941;
UPDATE fact_cards SET topic_ru = 'Мои комедии', question_ru = 'Какие комедии написал Абдулла Каххар?', fact_ru = 'Я писал и для сцены: среди моих комедий «Шёлковое сюзане» (1949–1953), «Больные зубы» (1954), «Голос из гроба» (1962) и «Матушки мои» (1967).' WHERE id = 1942;
UPDATE fact_cards SET topic_ru = 'Мои переводы', question_ru = 'Произведения каких писателей Абдулла Каххар перевёл на узбекский язык?', fact_ru = 'Я переводил из русской литературы: перевёл на узбекский произведения Пушкина, Толстого, Гоголя и Чехова.' WHERE id = 1943;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Абдулла Каххар?', fact_ru = 'В 1966 году я удостоился Государственной премии имени Хамзы, в 1967-м — звания «Народный писатель Узбекистана». Скончался 25 мая 1968 года в городе Москве.' WHERE id = 1944;
UPDATE fact_cards SET topic_ru = 'Моя память', question_ru = 'Какой наградой был отмечен Абдулла Каххар после смерти?', fact_ru = 'Я умер в 1968 году. В 2000 году мне был присвоен орден «За выдающиеся заслуги».' WHERE id = 1945;

-- ===== Said Ahmad =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Саид Ахмад?', fact_ru = 'Я родился 10 июня 1920 года в городе Ташкенте. Моё настоящее имя — Саидахмад Хусанходжаев, а «Саид Ахмад» — мой литературный псевдоним.' WHERE id = 2068;
UPDATE fact_cards SET topic_ru = 'Моя учёба и первая книга', question_ru = 'Где учился Саид Ахмад и каков его первый сборник?', fact_ru = 'Я учился в Ташкентском художественном училище, затем в 1940–1943 годах в Ташкентском педагогическом институте. Мой первый сборник рассказов «Подарок» вышел в 1940 году, а в юности я работал литсотрудником в журнале «Муштум».' WHERE id = 2069;
UPDATE fact_cards SET topic_ru = 'Моя трилогия «Горизонт»', question_ru = 'В какие годы создана трилогия Саида Ахмада «Горизонт»?', fact_ru = 'Моё самое крупное произведение — трилогия «Горизонт». Я писал её в 1964–1974 годах. А в 1988 году вышел мой роман «Тишина».' WHERE id = 2070;
UPDATE fact_cards SET topic_ru = '«Бунт невесток»', question_ru = 'Когда написана комедия Саида Ахмада «Бунт невесток»?', fact_ru = 'Я известен как мастер сатирических произведений. В 1976 году я написал комедию «Бунт невесток», в 1986-м — «Жених». Есть у меня и сборники «Ферганские рассказы» (1948) и «Степной орёл» (1960).' WHERE id = 2071;
UPDATE fact_cards SET topic_ru = 'Годы тяжких испытаний', question_ru = 'За что и когда был арестован Саид Ахмад?', fact_ru = 'В 1947 году меня арестовали по клевете, назвав «врагом народа». После смерти Сталина я был реабилитирован и продолжил творчество.' WHERE id = 2072;
UPDATE fact_cards SET topic_ru = 'Моя супруга Саида', question_ru = 'Кто была супругой Саида Ахмада?', fact_ru = 'Моя супруга — поэтесса Саида Зуннунова. Она родилась в 1926 году в городе Андижан и была автором книг «Ваша дочь написала» (1948) и «Долина цветов» (1954).' WHERE id = 2073;
UPDATE fact_cards SET topic_ru = 'Мои звания и награды', question_ru = 'Когда Саид Ахмад удостоился звания Героя Узбекистана?', fact_ru = 'В 1980 году мне присвоено звание народного писателя Узбекистана. В 1996 году я награждён орденом «Дустлик», в 1997-м — «За выдающиеся заслуги», а в 1999 году удостоен звания Героя Узбекистана.' WHERE id = 2074;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Саид Ахмад?', fact_ru = 'И в последние годы жизни я не откладывал перо: написал книги «Черноокий безумец» (2001) и «Заря, застывшая на ресницах» (2003). Я умер в 2007 году.' WHERE id = 2075;

-- ===== O'tkir Hoshimov =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Уткир Хашимов?', fact_ru = 'Я родился 5 августа 1941 года в ташкентской махалле Домбрабад. Моё детство пришлось на годы военных тягот и нужды.' WHERE id = 2076;
UPDATE fact_cards SET topic_ru = 'Учёба и работа', question_ru = 'Где учился и где работал Уткир Хашимов?', fact_ru = 'Работая, я учился на заочном отделении факультета журналистики Ташкентского государственного университета. Был заведующим отделом в газете «Тошкент оқшоми», заместителем главного редактора в издательстве имени Гафура Гуляма, затем главным редактором журнала «Шарк юлдузи».' WHERE id = 2077;
UPDATE fact_cards SET topic_ru = 'Моя первая книга', question_ru = 'Какова первая книга Уткира Хашимова и сколько произведений он написал всего?', fact_ru = 'Моя первая книга — «Стальной наездник» — вышла в 1962 году. Всего я написал более 50 произведений, они разошлись тиражом почти в 2 миллиона экземпляров.' WHERE id = 2078;
UPDATE fact_cards SET topic_ru = 'Повести моей молодости', question_ru = 'За какие произведения Уткир Хашимов получил в молодости Республиканскую премию для молодёжи?', fact_ru = 'Я написал произведения «Весна не вернётся» (1970), «Прислушайся к своему сердцу» (1973) и «Где свет, там и тень» (1976). В 1976 году за эти произведения я удостоился Республиканской премии для молодёжи.' WHERE id = 2079;
UPDATE fact_cards SET topic_ru = '«Дела мирские»', question_ru = 'Когда издана повесть «Дела мирские» и какую награду она принесла автору?', fact_ru = 'В 1982 году вышла моя повесть «Дела мирские». Это произведение было отмечено премией имени Айбека Союза писателей Узбекистана.' WHERE id = 2080;
UPDATE fact_cards SET topic_ru = '«Меж двух дверей»', question_ru = 'Когда издан роман «Меж двух дверей» и какую награду за него получил автор?', fact_ru = 'Мой роман «Меж двух дверей» издан в 1986 году. В том же 1986 году он удостоился Республиканской государственной премии имени Хамзы.' WHERE id = 2081;
UPDATE fact_cards SET topic_ru = 'Мои поздние произведения', question_ru = 'Когда вышла книга Уткира Хашимова «Записи на полях тетради» и какие сценические произведения он написал?', fact_ru = 'В 2001 году вышла моя книга «Записи на полях тетради». Я написал также сценические произведения «Увядшая весна», «С праздником свадьбы», «Лекарство совести».' WHERE id = 2082;
UPDATE fact_cards SET topic_ru = 'Мои звания и награды', question_ru = 'Каких званий и орденов удостоился Уткир Хашимов?', fact_ru = 'В 1991 году мне было присвоено звание «Народный писатель Узбекистана». В 1996 году я награждён орденом «Мехнат шухрати», в 2001-м — «За выдающиеся заслуги».' WHERE id = 2083;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда и где умер Уткир Хашимов?', fact_ru = 'Я скончался 24 мая 2013 года в городе Ташкенте.' WHERE id = 2084;
